import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

type Post = { id: number; title: string; author: string }

export default async function Home() {
  'use cache'
  // Revalidate the cached page every 1 hour.
  cacheLife('hours')
  // Tag the cache entry so it can be invalidated on-demand
  // with revalidateTag('posts') or updateTag('posts').
  cacheTag('posts')

  const posts: Post[] = await getPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}
